import React, { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { paperAPI } from '../utils/api';
import StatusBadge from './StatusBadge';
import { useAuth } from '../context/AuthContext';
import { Html5Qrcode } from 'html5-qrcode';

export default function ScanModal({ onClose }) {
  const nav = useNavigate();
  const { user } = useAuth();
  const [tab, setTab] = useState('camera'); // camera or manual
  const [ref, setRef]       = useState('');
  const [error, setError]   = useState('');
  const [result, setResult] = useState(null);
  const [suggestedAction, setSuggestedAction] = useState(null);
  const [note, setNote] = useState('');
  const [saving, setSaving] = useState(false);
  const [success, setSuccess] = useState('');
  const [cameraFacing, setCameraFacing] = useState('environment');
  const scannerRef = useRef(null);
  const startingRef = useRef(false);
  const mountedRef = useRef(false);
  const stopRequestedRef = useRef(false);
  const containerId = 'paper-scan-reader';

  const deriveSuggestedAction = (paper) => {
    const status = paper?.status_action || null;
    if (!status || status === 'OUT') return 'IN';
    if (status === 'IN') return 'OUT';
    return null;
  };

  const hydrateResult = (paper) => {
    setResult(paper);
    setRef(String(paper.ref_code || ''));
    setSuggestedAction(deriveSuggestedAction(paper));
    setNote('');
    setSuccess('');
  };

  useEffect(() => {
    mountedRef.current = true;
    if (tab === 'camera') {
      startCamera();
    } else {
      stopCamera();
    }
    return () => {
      mountedRef.current = false;
      stopCamera();
    };
  }, [tab]);

  useEffect(() => {
    if (tab !== 'camera') return;
    startCamera();
  }, [cameraFacing]);

  const getBestCameraConfig = async () => {
    try {
      const cameras = await Html5Qrcode.getCameras();
      if (Array.isArray(cameras) && cameras.length > 0) {
        const preferred = cameraFacing === 'user'
          ? cameras.find(c => /front|user/i.test(c.label)) || cameras[0]
          : cameras.find(c => /back|rear|environment/i.test(c.label)) || cameras[cameras.length - 1] || cameras[0];
        return preferred?.id || null;
      }
    } catch (e) {}
    return null;
  };

  const startCamera = async () => {
    try {
      if (startingRef.current) return;
      startingRef.current = true;
      stopRequestedRef.current = false;

      if (scannerRef.current) {
        try { await scannerRef.current.stop(); } catch (e) {}
        try { await scannerRef.current.clear(); } catch (e) {}
        scannerRef.current = null;
      }

      const container = document.getElementById(containerId);
      if (container) container.innerHTML = '';

      scannerRef.current = new Html5Qrcode(containerId);
      const config = { fps: 10, qrbox: { width: 250, height: 250 } };
      const cameraId = await getBestCameraConfig();
      const cameraConstraint = cameraId
        ? cameraId
        : { facingMode: { ideal: cameraFacing } };

      await scannerRef.current.start(
        cameraConstraint,
        config,
        async (decodedText) => {
          if (stopRequestedRef.current || !mountedRef.current) return;
          const parsed = parsePaperRef(decodedText);
          if (!parsed) {
            setError('Could not read a valid paper ref from the QR code.');
            return;
          }

          stopRequestedRef.current = true;
          await stopCamera();

          try {
            if (parsed.kind === 'id') {
              const r = await paperAPI.view(parsed.id);
              hydrateResult(r.data.paper);
            } else if (parsed.kind === 'ref') {
              const r = await paperAPI.scan(parsed.ref);
              hydrateResult(r.data.paper);
            }
          } catch (err) {
            setError(err.response?.data?.error || 'Not found.');
          }
        }
      );
    } catch (err) {
      const message = String(err?.message || err || '');
      if (message.includes('play() request was interrupted')) return;
      if (message.includes('The media was removed from the document')) return;
      if (cameraFacing === 'environment') {
        setCameraFacing('user');
        return;
      }

      const insecureContext = typeof window !== 'undefined'
        && window.location.protocol === 'http:'
        && !/^(localhost|127\.0\.0\.1)$/.test(window.location.hostname);
      setError(
        insecureContext
          ? 'Camera is blocked here because this page is opened over HTTP. Use HTTPS or localhost, then tap Retry Camera.'
          : 'Camera access failed. Allow camera permission, then tap Retry Camera.'
      );
    } finally {
      startingRef.current = false;
    }
  };

  const stopCamera = async () => {
    stopRequestedRef.current = true;
    if (scannerRef.current) {
      try { await scannerRef.current.stop(); } catch (e) {}
      try { await scannerRef.current.clear(); } catch (e) {}
      scannerRef.current = null;
    }
    if (mountedRef.current) {
      const container = document.getElementById(containerId);
      if (container) container.innerHTML = '';
    }
  };

  const parsePaperRef = (decodedText) => {
    if (!decodedText) return null;
    const s = String(decodedText).trim();
    // Try absolute URL first
    try {
      const u = new URL(s);
      const qref = u.searchParams.get('ref') || u.searchParams.get('id');
      if (qref && /^\d+$/.test(qref)) return { kind: 'ref', ref: qref };
      const m = u.pathname.match(/\/paper\/(\d+)/);
      if (m) return { kind: 'id', id: m[1] };
    } catch (e) {
      // ignore
    }

    // If not absolute, try treating as relative URL/path
    try {
      const u2 = new URL(s, window.location.origin);
      const qref = u2.searchParams.get('ref') || u2.searchParams.get('id');
      if (qref && /^\d+$/.test(qref)) return { kind: 'ref', ref: qref };
      const m2 = u2.pathname.match(/\/paper\/(\d+)/);
      if (m2) return { kind: 'id', id: m2[1] };
    } catch (e) {
      // ignore
    }

    // Fallback: prefer last numeric group (avoids matching ports like 3000)
    const all = Array.from(s.matchAll(/(\d{1,10})/g)).map(m => m[1]);
    if (all.length) {
      const last = all[all.length - 1];
      return { kind: 'ref', ref: last };
    }

    return null;
  };

  const lookupPaper = async (value = ref) => {
    if (!value) return;
    setError('');
    setResult(null);
    setSuccess('');
    try {
      const r = await paperAPI.scan(value);
      hydrateResult(r.data.paper);
    } catch (err) {
      setError(err.response?.data?.error || 'Not found.');
    }
  };

  const lookup = async (e) => {
    e.preventDefault();
    await lookupPaper(ref);
  };

  const confirmAction = async () => {
    if (!result || !suggestedAction) return;
    setSaving(true);
    setError('');
    setSuccess('');
    try {
      await paperAPI.mark({
        paper_id: result.id,
        action: suggestedAction,
        dept_id: user?.dept_id,
        note: note.trim() || 'manual',
      });
      const refreshed = await paperAPI.scan(result.ref_code);
      hydrateResult(refreshed.data.paper);
      setSuccess(`Document successfully marked ${suggestedAction}.`);
    } catch (err) {
      setError(err.response?.data?.error || 'Failed to save status update.');
    } finally {
      setSaving(false);
    }
  };

  const goTo = () => { nav(`/paper/${result.id}`); onClose(); };

  return (
    <div className="overlay" onClick={e => e.target === e.currentTarget && onClose()}>
      <div className="modal">
        <div className="modal-head">
          <span className="modal-title">📷 Scan / Lookup</span>
          <button className="btn btn-outline btn-sm" onClick={onClose}>✕</button>
        </div>
        <div className="modal-body">
          <div style={{ display: 'flex', gap: 8, marginBottom: 16, borderBottom: '1px solid var(--border)' }}>
            <button 
              className={`btn btn-sm ${tab === 'camera' ? 'btn-navy' : 'btn-outline'}`}
              onClick={() => setTab('camera')}
              style={{ borderBottom: tab === 'camera' ? '3px solid var(--navy)' : 'none' }}
            >
              📷 Camera
            </button>
            <button 
              className={`btn btn-sm ${tab === 'manual' ? 'btn-navy' : 'btn-outline'}`}
              onClick={() => setTab('manual')}
              style={{ borderBottom: tab === 'manual' ? '3px solid var(--navy)' : 'none' }}
            >
              ✏️ Manual
            </button>
          </div>

          {error && <div className="alert a-err">{error}</div>}
          {success && <div className="alert a-ok">{success}</div>}

          {tab === 'camera' && (
            <div style={{ marginBottom: 16 }}>
              <div className="camera-switch-row">
                <button type="button" className={`btn btn-sm ${cameraFacing === 'environment' ? 'btn-navy' : 'btn-outline'}`} onClick={() => setCameraFacing('environment')}>
                  📷 Back Camera
                </button>
                <button type="button" className={`btn btn-sm ${cameraFacing === 'user' ? 'btn-navy' : 'btn-outline'}`} onClick={() => setCameraFacing('user')}>
                  🤳 Front Camera
                </button>
              </div>
              {error && (
                <div style={{ display: 'flex', gap: 8, marginBottom: 12, flexWrap: 'wrap' }}>
                  <button type="button" className="btn btn-navy btn-sm" onClick={startCamera}>
                    Retry Camera
                  </button>
                  <button type="button" className="btn btn-outline btn-sm" onClick={() => setTab('manual')}>
                    Use Manual Entry
                  </button>
                </div>
              )}
              <div id={containerId} style={{ width: '100%', borderRadius: 8, overflow: 'hidden', minHeight: 300, background: '#000' }} />
              <p style={{ fontSize: 12, color: 'var(--t2)', marginTop: 8, textAlign: 'center' }}>
                Point camera at QR code or barcode
              </p>
            </div>
          )}

          {tab === 'manual' && (
            <form onSubmit={lookup} style={{ display:'flex', gap:8, marginBottom: 16 }}>
              <input 
                className="inp" 
                type="text" 
                placeholder="Enter Ref Code (e.g. 1, 25, 152)"
                value={ref} 
                onChange={e => setRef(e.target.value)} 
                required 
              />
              <button type="submit" className="btn btn-navy" style={{ whiteSpace:'nowrap' }}>
                Look Up
              </button>
            </form>
          )}

          {tab === 'camera' && ref && (
            <div style={{ marginBottom: 16 }}>
              <p style={{ fontSize: 12, color: 'var(--t2)' }}>Detected: <strong>{ref}</strong></p>
              <button onClick={lookup} className="btn btn-navy" style={{ width: '100%' }}>
                Look Up Code
              </button>
            </div>
          )}

          {result && (
            <div className="card mt4">
              <div className="card-body">
                <div className="alert a-ok mb2">✅ Paper found!</div>
                <table style={{ width:'100%' }}>
                  <tbody>
                    {[
                      ['Ref', <span className="mono" style={{fontSize:20,fontWeight:800,color:'var(--navy)'}}>#{result.ref_code}</span>],
                      ['Title', result.title],
                      ['Origin', result.origin],
                      ['Status', <StatusBadge action={result.status_action} dept={result.status_dept} />],
                      ['Current Location', result.current_location || '—'],
                      ['Last Scan', result.last_scanned_at ? new Date(result.last_scanned_at).toLocaleString('en-PH') : '—'],
                      ['Suggested Action', suggestedAction ? `Mark ${suggestedAction}` : 'No action available'],
                    ].map(([k,v]) => (
                      <tr key={k} style={{ borderBottom:'1px solid var(--border)' }}>
                        <td style={{ padding:'8px 0', fontWeight:600, fontSize:11, color:'var(--t2)', width:70, textTransform:'uppercase' }}>{k}</td>
                        <td style={{ padding:'8px 0' }}>{v}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>

                {suggestedAction && (
                  <div style={{ marginTop: 14, paddingTop: 14, borderTop: '1px solid var(--border)' }}>
                    <label className="lbl" style={{ marginBottom: 8 }}>Note / Remarks</label>
                    <textarea
                      className="inp"
                      rows="3"
                      placeholder="Optional note for this movement"
                      value={note}
                      onChange={e => setNote(e.target.value)}
                      style={{ resize: 'vertical' }}
                    />
                    <div style={{ display: 'flex', gap: 8, marginTop: 12 }}>
                      <button type="button" className="btn btn-navy" onClick={confirmAction} disabled={saving}>
                        {saving ? 'Saving…' : `Confirm ${suggestedAction}`}
                      </button>
                      <button type="button" className="btn btn-outline" onClick={() => setNote('')} disabled={saving}>
                        Clear Note
                      </button>
                    </div>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
        <div className="modal-foot">
          <button className="btn btn-outline" onClick={async () => { await stopCamera(); onClose(); }}>Close</button>
          {result && <button className="btn btn-navy" onClick={goTo}>View Full Details →</button>}
        </div>
      </div>
    </div>
  );
}
